#!/bin/sh
# Generated by `coder-eval export --format harbor` — do not hand-edit; a
# regenerated export will overwrite it. See tmp/harborframework.md § C1.1.
#
# NOT `set -e`: `coder-eval evaluate` exits non-zero whenever any criterion
# fails its gate -- a genuine MEASURED verdict, not an infrastructure
# failure. `set -e` here would abort before `coder-eval harbor reward` ever
# ran, turning every real failing score into a masked (unmeasured) trial --
# confirmed live: a solution that runs but produces the wrong content
# scored weighted_score=0.500 in task.json, yet `set -e` discarded it and
# Harbor reported RewardFileNotFoundError instead of reward=0.5. The reward
# writer is what decides infra-vs-policy (None -> no file); this script must
# always reach it.
set -u

# `/tests/task.yaml /logs/agent` -- an explicit task file over a RUN DIRECTORY,
# not a plain workdir. CoderEvalAgent's `coder-eval execute --run-dir /logs/agent
# --workspace-dir "$(pwd)" --no-capture-workspace` always finishes with
# `/logs/agent/task.json` (this task's own recorded trajectory) and the agent's
# workspace left in-place at the container's own WORKDIR ($(pwd) here too --
# Harbor's verifier phase reuses the same image/WORKDIR) -- NOT copied into
# `/logs/agent/artifacts/<task_id>/`, since --no-capture-workspace skips that
# copy (Harbor collects the WORKDIR itself). `--workspace "$(pwd)"` is therefore load-bearing:
# without it, `coder-eval evaluate` resolves the workspace from task.json's
# recorded sandbox_path via `default_workspace`, which requires it to resolve
# INSIDE /logs/agent and refuses otherwise -- exactly this WORKDIR case, which
# is legitimately outside /logs/agent. No ATIF trajectory.json round-trip either
# (task.json already carries the same trajectory natively). Passing the task
# file explicitly (rather than the bare run directory alone) makes coder-eval
# grade with THIS file -- the exported contract -- instead of rebuilding the
# task from the run's own recorded config, which is also what keeps this off
# the untrusted-recorded-config path: that path exists for a shared run
# directory whose config is not to be trusted without --allow-recorded-commands,
# and does not apply once an explicit, operator-supplied task file is in hand.
coder-eval evaluate /tests/task.yaml /logs/agent --workspace "$(pwd)" --in-place --run-dir /logs/verifier || true
coder-eval harbor reward /logs/verifier --out /logs/verifier/reward.json
